<script setup>import {Head,Link,useForm,usePage} from '@inertiajs/vue3';import {computed,ref} from 'vue';import TurnstileWidget from '../../Components/TurnstileWidget.vue';import CustomerShell from '../../Components/CustomerShell.vue';const page=usePage(),turnstile=ref(null),security=computed(()=>page.props.security||{}),form=useForm({name:'',email:'',phone:'',password:'',password_confirmation:'',turnstile_token:''});const submit=()=>form.post('/register',{onFinish:()=>{form.reset('password','password_confirmation');turnstile.value?.reset()}});</script>
<template><Head title="Daftar"/><CustomerShell compact-footer><main class="lf-auth-wrap"><form class="lf-auth-card" @submit.prevent="submit"><p class="lf-eyebrow">Buat akun</p><h1>Daftar LFAMILIA</h1><p>Buat akun untuk saldo, riwayat pesanan, membership, dan layanan pelanggan.</p><div class="grid gap-3"><label v-for="x in [{k:'name',l:'Nama',t:'text'},{k:'email',l:'Email',t:'email'},{k:'phone',l:'Nomor telepon',t:'tel'}]" :key="x.k" class="text-[10px] font-semibold text-white/70">{{x.l}}<input v-model="form[x.k]" :type="x.t" required></label><label class="text-[10px] font-semibold text-white/70">Kata sandi (minimal 12 karakter)<input v-model="form.password" type="password" minlength="12" required></label><label class="text-[10px] font-semibold text-white/70">Ulangi kata sandi<input v-model="form.password_confirmation" type="password" required></label><TurnstileWidget v-if="security.turnstile_required" ref="turnstile" :site-key="security.turnstile_site_key" :action="security.turnstile_action" @token="form.turnstile_token=$event"/><button class="lf-primary w-full" :disabled="form.processing">Daftar</button><a href="/auth/google/redirect" class="lf-secondary w-full">Daftar dengan Google</a></div><div class="lf-auth-links justify-end"><Link href="/login">Sudah punya akun? Masuk</Link></div></form></main></CustomerShell></template>